import type { Question } from './types';

const Q = (q: Question) => q;

export const questions: Question[] = [
  // ── 1 Foundations ───────────────────────────────────────────────────────────
  Q({ id: 'f-causal', module: 'foundations', level: 'appraise', stem: 'A model predicting death from pneumonia assigns lower risk to patients with asthma. What is the best interpretation?', options: ['Asthma protects against death from pneumonia', 'The model reflects risk under current care: asthmatic patients were treated more intensively, lowering their observed mortality', 'The model is miscalibrated and should be recalibrated', 'Asthma should be removed because only causal predictors are allowed'], answer: 1, explanation: 'Prediction models estimate risk under the care patients actually received. Asthmatic patients were escalated faster, so their observed mortality was lower (Caruana 2015). The association is real but not causal; using it to withhold care would be dangerous. Non-causal predictors are allowed in prediction models — they just must not be read as treatment targets.', refs: ['caruana2015', 'vangeloven2020'] }),
  Q({ id: 'f-ppv', module: 'foundations', level: 'apply', stem: 'A sepsis alert has sensitivity 80% and specificity 90%. On a ward where 2% of patients develop sepsis, approximately what proportion of alerts are true cases?', options: ['80%', '47%', '14%', '2%'], answer: 2, explanation: 'Per 1,000 patients: 20 have sepsis → 16 true alerts; 980 do not → 98 false alerts. PPV = 16 / 114 ≈ 14%. Low prevalence lets false positives from the large healthy group dominate.' }),
  Q({ id: 'f-ladder', module: 'foundations', level: 'appraise', stem: 'Which finding gives the strongest evidence that using a model improves patient outcomes?', options: ['AUC 0.91 in 50,000 patients with bootstrap validation', 'Good calibration at external validation in five countries', 'A cluster-randomised trial showing lower mortality on wards using the model', 'Regulatory clearance as a medical device'], answer: 2, explanation: 'Accuracy and calibration are necessary but do not show that acting on the model changes outcomes. Only comparative impact studies (ideally randomised) do. Regulatory clearance is often based on retrospective accuracy.', refs: ['kappen2018impact'] }),
  Q({ id: 'f-index', module: 'foundations', level: 'appraise', stem: 'A model to be used at the moment of ward admission predicts ICU transfer. One predictor is "number of vital-sign sets recorded in the first 24 h". What is the main problem?', options: ['The predictor is a count variable', 'It is not available at the moment of prediction and reflects clinician concern — leakage', 'It needs a spline', 'It will reduce calibration but not discrimination'], answer: 1, explanation: 'The predictor is measured after the index time and is driven by staff worry about the patient. It inflates retrospective performance and cannot be used at admission.' }),
  Q({ id: 'f-lr', module: 'foundations', level: 'apply', stem: 'Pre-test probability is 20%. A "high-risk" model output has a likelihood ratio of 4. What is the post-test probability?', options: ['80%', '50%', '44%', '24%'], answer: 1, explanation: 'Pre-test odds = 0.2/0.8 = 0.25. Post-test odds = 0.25 × 4 = 1.0. Probability = 1/(1+1) = 50%.' }),
  Q({ id: 'f-compare', module: 'foundations', level: 'appraise', stem: 'Two published "sepsis prediction" models report AUCs of 0.88 and 0.72. What should you check first before concluding the first is better?', options: ['Which used deep learning', 'Whether they predict the same outcome definition, from the same index time and horizon, in comparable populations', 'Which has more predictors', 'Which was published in a higher-impact journal'], answer: 1, explanation: 'AUCs are only comparable for the same prediction problem. A model predicting sepsis 1 hour ahead from ICU data, using a billing-code label, solves a far easier problem than one predicting Sepsis-3 48 h ahead on wards.' }),

  // ── 2 Data & design ─────────────────────────────────────────────────────────
  Q({ id: 'd-leak', module: 'data-design', level: 'apply', stem: 'Which candidate predictor is most likely to cause leakage in a model that predicts sepsis at the time of ED triage?', options: ['Triage heart rate', 'Age', 'Blood culture ordered during the ED stay', 'History of diabetes'], answer: 2, explanation: 'A blood culture order happens after triage and only because a clinician suspects infection. It encodes the outcome process and is not available at the moment of prediction.' }),
  Q({ id: 'd-params', module: 'data-design', level: 'apply', stem: 'A model will consider age (4-knot restricted cubic spline), sex, smoking (4 categories) and three laboratory values modelled linearly. How many candidate predictor parameters are there?', options: ['6', '8', '10', '12'], answer: 2, explanation: 'Age spline with 4 knots = 3 parameters; sex = 1; smoking with 4 categories = 3; three linear labs = 3. Total = 10. Sample-size calculations must use parameters, not variables.', refs: ['riley2020samplesize'] }),
  Q({ id: 'd-epv', module: 'data-design', level: 'recall', stem: 'Which statement about the "10 events per variable" rule is correct?', options: ['It guarantees a calibrated model', 'It came from simulations of coefficient bias and does not ensure accurate predictions; required size depends on parameters, prevalence and expected model fit', 'It applies to parameters retained after selection only', 'Machine-learning models need fewer events per variable than regression'], answer: 1, explanation: 'EPV 10 originated from regression-coefficient simulations (Peduzzi 1996). Sample size for prediction should be calculated (Riley 2020), counting all candidate parameters. Flexible ML methods typically need more data, not less.', refs: ['peduzzi1996', 'vansmeden2019epv', 'riley2020samplesize'] }),
  Q({ id: 'd-casecontrol', module: 'data-design', level: 'apply', stem: 'A diagnostic model is developed in a case–control sample with 50% cases. The prevalence in practice is 5%. Without adjustment, its predicted risks in practice will be:', options: ['About right', 'Systematically too high', 'Systematically too low', 'Unaffected, because AUC is unchanged'], answer: 1, explanation: 'The intercept reflects the 50% sampling fraction. Applied where prevalence is 5%, predictions are far too high. Ranking (AUC) can be preserved, but absolute risks need re-weighting or an intercept correction.' }),
  Q({ id: 'd-missing', module: 'data-design', level: 'appraise', stem: 'During development, multiple imputation included the outcome in the imputation model. What does this imply for real-time deployment?', options: ['The deployed model must also impute using the outcome', 'A separate strategy that uses only information available at prediction time must be specified', 'Missing predictors can be set to zero', 'Patients with any missing value must be excluded at deployment'], answer: 1, explanation: 'Including the outcome is correct for development imputation, but the outcome is unknown at the bedside. The deployment strategy (e.g., imputation from predictors, missing indicators) must be specified and evaluated.', refs: ['sperrin2020missing', 'sisk2023missing'] }),
  Q({ id: 'd-ml-data', module: 'data-design', level: 'recall', stem: 'Compared with logistic regression, flexible methods such as random forests and neural networks generally need:', options: ['Fewer events to reach stable performance', 'A similar number of events', 'Substantially more events to keep optimism small', 'No sample-size consideration because they self-regularise'], answer: 2, explanation: 'In simulation, modern methods needed over ten times as many events per variable as logistic regression to achieve small optimism (van der Ploeg 2014).', refs: ['vanderploeg2014'] }),

  // ── 3 Logistic regression ───────────────────────────────────────────────────
  Q({ id: 'l-or', module: 'logistic', level: 'apply', stem: 'An exposure has an odds ratio of 2.0. For a patient whose baseline risk is 40%, the risk with the exposure is approximately:', options: ['80%', '57%', '60%', '48%'], answer: 1, explanation: 'Baseline odds = 0.4/0.6 = 0.667. × 2 = 1.333. Risk = 1.333/2.333 = 57%. The risk ratio here is 1.43, not 2: an OR overstates the RR when the outcome is common.' }),
  Q({ id: 'l-calc', module: 'logistic', level: 'apply', stem: 'A model has linear predictor LP = −2 + 0.5x. What is the predicted risk when x = 2?', options: ['27%', '50%', '37%', '12%'], answer: 0, explanation: 'LP = −2 + 1 = −1. p = 1/(1 + e¹) = 1/3.718 = 0.269 ≈ 27%.' }),
  Q({ id: 'l-step', module: 'logistic', level: 'recall', stem: 'Why is stepwise variable selection by p-values discouraged for prediction models?', options: ['It is computationally slow', 'It overestimates retained coefficients, underestimates their standard errors and is unstable across samples', 'It always removes the most important predictors', 'It cannot be used with splines'], answer: 1, explanation: 'Selection on significance picks predictors whose effects were by chance large in this sample (a winner’s curse), so they shrink in new data; the reported SEs ignore the selection; and the chosen set changes between bootstrap samples.', refs: ['harrell2015rms'] }),
  Q({ id: 'l-dichot', module: 'logistic', level: 'recall', stem: 'Why model lactate with a restricted cubic spline rather than as "≥ 2 vs < 2 mmol/L"?', options: ['Splines make the model causal', 'Dichotomising discards information and imposes a step in risk at an arbitrary point; splines capture smooth nonlinearity', 'Splines always improve AUC by > 0.05', 'Dichotomised variables cannot be used in logistic regression'], answer: 1, explanation: 'Categorising loses power (roughly like discarding a third of the data for a median split) and treats 2.1 and 9.0 the same. Splines let the data show the shape.', refs: ['royston2006dichot'] }),
  Q({ id: 'l-collinear', module: 'logistic', level: 'appraise', stem: 'Urea and creatinine are strongly correlated and both included in a logistic model. What is the main consequence?', options: ['Predictions become biased', 'Individual coefficients are unstable and hard to interpret, but predictions are largely unaffected', 'The model cannot be fitted', 'Calibration fails'], answer: 1, explanation: 'Collinearity inflates the variance of individual coefficients, but their combined contribution, and so the predictions, remains well estimated within the range of the data.' }),
  Q({ id: 'l-intercept', module: 'logistic', level: 'recall', stem: 'A paper presents a logistic prediction model with odds ratios for each predictor but no intercept. What can you not do?', options: ['Rank patients by risk', 'Compute absolute predicted probabilities', 'Identify the strongest predictor', 'Compute relative odds between two patients'], answer: 1, explanation: 'Without the intercept, the linear predictor is only known up to a constant. You can rank patients, but not compute probabilities. TRIPOD+AI requires the full model.', refs: ['collins2024tripodai'] }),
  Q({ id: 'l-ml', module: 'logistic', level: 'recall', stem: 'What did a systematic review of ML vs logistic regression for clinical prediction (Christodoulou 2019) find?', options: ['ML improved AUC by about 0.1 on average', 'No average AUC difference in comparisons at low risk of bias', 'Logistic regression was always better', 'ML was better only in small samples'], answer: 1, explanation: 'Across 71 studies, comparisons at low risk of bias showed no difference in AUC; apparent ML advantages came from comparisons at high risk of bias.', refs: ['christodoulou2019'] }),

  // ── 4 Survival ──────────────────────────────────────────────────────────────
  Q({ id: 's-km', module: 'survival', level: 'apply', stem: 'Just before day 10, Kaplan–Meier survival is 0.80 and 40 patients are at risk. Four die on day 10 (and two others are censored that day). What is S(10)?', options: ['0.72', '0.76', '0.70', '0.80'], answer: 0, explanation: 'S(10) = 0.80 × (1 − 4/40) = 0.72. Patients censored at day 10 are counted at risk on that day and then leave the risk set.' }),
  Q({ id: 's-competing', module: 'survival', level: 'appraise', stem: 'You are predicting 10-year hip-fracture risk in people aged 85+, many of whom die first. If deaths are treated as censored and risk is estimated as 1 − Kaplan–Meier, the estimate will be:', options: ['Unbiased', 'Too high', 'Too low', 'Unaffected by mortality'], answer: 1, explanation: 'Censoring deaths assumes those patients could still fracture later, so 1 − KM estimates risk in a hypothetical world without death. Cumulative incidence (Aalen–Johansen / Fine–Gray) gives the real-world absolute risk.', refs: ['austin2016competing'] }),
  Q({ id: 's-hr', module: 'survival', level: 'recall', stem: 'A Cox model gives a hazard ratio of 2.0 for diabetes. Which interpretation is correct?', options: ['Diabetic patients have twice the 5-year risk', 'Among patients still event-free at any time, the instantaneous event rate is twice as high in diabetics (assuming proportional hazards)', 'Diabetes doubles survival time', 'Half of diabetics will have the event'], answer: 1, explanation: 'A hazard ratio compares instantaneous rates. Cumulative risk ratios at a horizon are smaller than the HR when events are common.', refs: ['hernan2010hazards'] }),
  Q({ id: 's-baseline', module: 'survival', level: 'recall', stem: 'To compute a patient’s 10-year absolute risk from a Cox model you need:', options: ['Only the hazard ratios', 'The baseline survival at 10 years and the patient’s linear predictor (with centring values)', 'The Kaplan–Meier median', 'The C-index'], answer: 1, explanation: 'Risk = 1 − S₀(10)^exp(LP). Many publications omit S₀(t), which makes the model unusable for prediction.' }),
  Q({ id: 's-noninf', module: 'survival', level: 'recall', stem: 'Which assumption does Kaplan–Meier estimation require?', options: ['Normally distributed survival times', 'Proportional hazards', 'Non-informative censoring', 'No more than 20% censoring'], answer: 2, explanation: 'KM is valid with any amount of censoring as long as censored patients have the same prognosis as those who remain under follow-up. Proportional hazards is a Cox-model assumption.' }),
  Q({ id: 's-cross', module: 'survival', level: 'appraise', stem: 'Kaplan–Meier curves for two treatments cross at 12 months. What does this suggest?', options: ['The treatments are equivalent', 'Proportional hazards is violated, so a single hazard ratio is misleading', 'Censoring is informative', 'The log-rank test is the best summary'], answer: 1, explanation: 'Crossing curves imply the hazard ratio changes over time. Use time-varying effects, restricted mean survival time, or report effects by period.', refs: ['grambsch1994'] }),

  // ── 5 Trees ─────────────────────────────────────────────────────────────────
  Q({ id: 't-gini', module: 'trees', level: 'apply', stem: 'A node contains 100 patients, 30 with the outcome. What is its Gini impurity?', options: ['0.21', '0.42', '0.30', '0.50'], answer: 1, explanation: 'Gini = 2p(1 − p) = 2 × 0.3 × 0.7 = 0.42.' }),
  Q({ id: 't-boost', module: 'trees', level: 'recall', stem: 'In gradient boosting, lowering the learning rate from 0.3 to 0.03 typically means:', options: ['Fewer boosting rounds are needed', 'More rounds are needed, often with better generalisation; choose the number by early stopping', 'Deeper trees are required', 'The model becomes a random forest'], answer: 1, explanation: 'Each tree contributes less, so more rounds are needed; small steps usually generalise better. The number of rounds should be tuned on validation data.' }),
  Q({ id: 't-rf', module: 'trees', level: 'recall', stem: 'Why does a random forest consider only a random subset of predictors at each split?', options: ['To speed up prediction', 'To decorrelate the trees, so averaging reduces variance more', 'To perform variable selection', 'To make each tree interpretable'], answer: 1, explanation: 'If one strong predictor dominated every tree, the trees would be highly correlated and averaging would help little. Feature subsampling decorrelates them.', refs: ['breiman2001rf'] }),
  Q({ id: 't-impurity', module: 'trees', level: 'appraise', stem: 'Impurity-based ("Gini") importance from a random forest ranks a continuous lab value far above a binary comorbidity. Why be cautious?', options: ['Continuous variables are always less important', 'Impurity importance is biased toward continuous and high-cardinality predictors, which offer more split points', 'Gini importance is only valid for regression', 'The forest must be miscalibrated'], answer: 1, explanation: 'Strobl et al. (2007) showed this bias. Prefer permutation importance or SHAP, while remembering their own caveats.', refs: ['strobl2007'] }),
  Q({ id: 't-slope', module: 'trees', level: 'apply', stem: 'A random forest has a calibration slope of 1.3 on validation data. What does this mean?', options: ['Predictions are too extreme', 'Predictions are too modest (squeezed toward the average)', 'It is overfitted', 'Discrimination is poor'], answer: 1, explanation: 'A slope above 1 means observed risks spread out more than the predictions: high risks are under-predicted and low risks over-predicted. Recalibrate, e.g., with logistic (Platt) recalibration.' }),
  Q({ id: 't-tune', module: 'trees', level: 'appraise', stem: 'A study tried 200 hyperparameter settings and reported the best AUC on its test set. What is the problem?', options: ['Too few settings were tried', 'The test set was used for model selection, so the reported AUC is optimistic', 'Hyperparameters should never be tuned', 'AUC is the wrong metric'], answer: 1, explanation: 'Selecting the best of many on the test data turns the test set into a validation set. Tune with (nested) cross-validation on training data and use the test set once.' }),

  // ── 6 Neural ────────────────────────────────────────────────────────────────
  Q({ id: 'n-calib', module: 'neural', level: 'recall', stem: 'Modern deep neural networks used as classifiers tend to be:', options: ['Well calibrated by default', 'Over-confident; temperature scaling on validation data largely corrects this', 'Under-confident', 'Calibrated only when trained with dropout'], answer: 1, explanation: 'Guo et al. (2017) showed modern networks are over-confident and that a single temperature parameter fitted on held-out data fixes most of it.', refs: ['guo2017calib'] }),
  Q({ id: 'n-shortcut', module: 'neural', level: 'appraise', stem: 'A chest-radiograph model has AUC 0.93 on a random split from hospital A but 0.70 at hospital B, and it can identify which hospital an image came from. What is the most likely explanation?', options: ['Hospital B patients are healthier', 'Shortcut learning: the model uses site-specific features that correlate with disease prevalence at A', 'Too few training epochs', 'Hospital B uses higher-resolution images'], answer: 1, explanation: 'Zech et al. (2018) found exactly this pattern. Random splits within one source keep the shortcut in both train and test; only external validation exposes it.', refs: ['zech2018'] }),
  Q({ id: 'n-tabular', module: 'neural', level: 'recall', stem: 'On typical tabular data (e.g., vital signs and labs), compared with gradient-boosted trees, deep networks:', options: ['Consistently outperform them', 'Usually do not outperform them', 'Need less data', 'Are better calibrated'], answer: 1, explanation: 'Benchmark studies show tree ensembles remain state of the art on typical tabular data (Grinsztajn 2022).', refs: ['grinsztajn2022'] }),
  Q({ id: 'n-logistic', module: 'neural', level: 'recall', stem: 'A neural network with no hidden layer and a sigmoid output unit trained on log-loss is equivalent to:', options: ['A decision tree', 'Logistic regression', 'A random forest', 'Linear discriminant analysis with equal priors'], answer: 1, explanation: 'Output = sigmoid(w·x + b), fitted by maximising the Bernoulli likelihood — logistic regression.' }),
  Q({ id: 'n-early', module: 'neural', level: 'apply', stem: 'Training loss keeps falling, but validation loss reached its minimum at epoch 40 and has risen since. What is the best action?', options: ['Train longer', 'Use the weights from about epoch 40 (early stopping) and/or add regularisation', 'Increase the learning rate', 'Add more hidden units'], answer: 1, explanation: 'Rising validation loss with falling training loss is overfitting. Early stopping and weight decay are standard remedies.' }),

  // ── 7 Validation ────────────────────────────────────────────────────────────
  Q({ id: 'v-bootstrap', module: 'validation', level: 'recall', stem: 'For a logistic model developed on 600 patients, which internal validation approach is generally preferred?', options: ['A single 70/30 random split', 'Bootstrap optimism correction that repeats the whole modelling process, including any selection', 'Apparent performance with a large number of predictors', 'Testing on the training data after shrinkage'], answer: 1, explanation: 'Bootstrapping uses all the data for development and gives a stable estimate of optimism, provided every modelling step is repeated in each bootstrap sample.', refs: ['steyerberg2001internal', 'harrell2015rms'] }),
  Q({ id: 'v-update', module: 'validation', level: 'apply', stem: 'At a new hospital a model has AUC 0.80 (as in development) and a calibration slope of 1.0, but observed/expected = 1.5. What is the best first step?', options: ['Re-develop the model with local data', 'Update the intercept (recalibration-in-the-large)', 'Add new predictors', 'Abandon the model'], answer: 1, explanation: 'Ranking and spread are fine; only the baseline risk differs. A one-parameter intercept update fixes this with modest data.', refs: ['janssen2008updating'] }),
  Q({ id: 'v-patient', module: 'validation', level: 'appraise', stem: 'A dataset has 5 images each for 1,000 patients and is split randomly by image into training and test sets. What is the problem?', options: ['Too few images per patient', 'The same patients appear in both sets — leakage; split by patient', 'Images should be split by date', 'There is no problem if the split is stratified'], answer: 1, explanation: 'Images from one patient share anatomy and acquisition artefacts. The model can memorise patients, inflating test performance.' }),
  Q({ id: 'v-select', module: 'validation', level: 'appraise', stem: 'Researchers select the 20 genes most associated with the outcome using all 80 patients, then report a 5-fold cross-validated AUC of 0.89. What is the most likely issue?', options: ['Too few folds', 'Feature selection outside the cross-validation loop has leaked test information, so the AUC is optimistic', 'Gene expression must be log-transformed', 'Cross-validation should be replaced with a 50/50 split'], answer: 1, explanation: 'Selection must be repeated inside each training fold. With pure noise, the "wrong way" commonly yields AUCs of 0.8–0.9 (see the leakage lab).', refs: ['hastie2009esl', 'varma2006nested'] }),
  Q({ id: 'v-temporal', module: 'validation', level: 'recall', stem: 'A model will be used prospectively at the developing hospital. Which validation best approximates that use?', options: ['Random cross-validation across all years', 'Temporal validation: freeze the model and test it on later patients', 'Apparent performance', 'Validation on a public benchmark dataset'], answer: 1, explanation: 'Temporal validation mimics deployment: the model only sees the past and is tested on the future, capturing drift in practice and data systems.' }),
  Q({ id: 'v-epic', module: 'validation', level: 'recall', stem: 'An independent external validation of a widely deployed proprietary sepsis model (Wong 2021) found:', options: ['AUC 0.83, consistent with the developer', 'AUC 0.63, with low sensitivity and PPV at the alert threshold and frequent alerts', 'Perfect calibration', 'Improved mortality'], answer: 1, explanation: 'AUC was 0.63 (developer reported 0.76–0.83); at the threshold sensitivity was 33% and PPV 12%; 18% of hospitalised patients triggered alerts.', refs: ['wong2021epic'] }),

  // ── 8 Discrimination ────────────────────────────────────────────────────────
  Q({ id: 'c-acc', module: 'discrimination', level: 'apply', stem: 'The outcome prevalence is 3%. A model that flags nobody has an accuracy of:', options: ['3%', '50%', '97%', 'Undefined'], answer: 2, explanation: 'Every negative (97%) is correctly classified, every case is missed. Accuracy rewards ignoring rare outcomes.' }),
  Q({ id: 'c-auc', module: 'discrimination', level: 'recall', stem: 'An AUC of 0.80 means:', options: ['80% of patients are correctly classified', 'There is an 80% probability that a random patient with the outcome has a higher predicted risk than a random patient without it', 'Sensitivity is 80% at the optimal threshold', 'Predicted risks are 80% accurate'], answer: 1, explanation: 'AUC is the concordance probability (Hanley & McNeil 1982). It is threshold-free and says nothing about calibration.', refs: ['hanley1982'] }),
  Q({ id: 'c-smote', module: 'discrimination', level: 'appraise', stem: 'A team oversamples cases with SMOTE to turn 5% prevalence into 50% before fitting logistic regression. What is the expected effect on the deployed model?', options: ['Better calibration', 'Systematically over-estimated risks, with no gain in AUC', 'Higher AUC and unchanged calibration', 'No effect'], answer: 1, explanation: 'Rebalancing shifts the intercept and distorts calibration (van den Goorbergh 2022). If more positives are wanted, lower the threshold on calibrated risks.', refs: ['vandengoorbergh2022'] }),
  Q({ id: 'c-pr', module: 'discrimination', level: 'recall', stem: 'Which statement about the area under the precision–recall curve (AUPRC) is correct?', options: ['Its chance baseline is 0.5', 'Its chance baseline equals prevalence, so it cannot be compared across populations with different event rates', 'It is unaffected by prevalence', 'It is always preferable to AUC for imbalanced data'], answer: 1, explanation: 'Precision depends on prevalence. AUPRC is informative about alert burden but is not universally superior and is not portable across settings (McDermott 2024).', refs: ['saito2015pr', 'mcdermott2024auprc'] }),
  Q({ id: 'c-youden', module: 'discrimination', level: 'appraise', stem: 'Choosing the threshold that maximises Youden’s index (sensitivity + specificity − 1) implicitly assumes:', options: ['False negatives are more harmful than false positives', 'Sensitivity and specificity are equally important, regardless of clinical consequences', 'The model is perfectly calibrated', 'Prevalence is 50%'], answer: 1, explanation: 'Youden ignores the consequences of each error. Clinical thresholds should come from harm–benefit trade-offs and capacity.' }),
  Q({ id: 'c-nne', module: 'discrimination', level: 'apply', stem: 'At the chosen threshold an alert has PPV 20%. How many alerts must be evaluated per true case?', options: ['2', '4', '5', '20'], answer: 2, explanation: 'Number needed to evaluate = 1 / PPV = 1 / 0.2 = 5.' }),
  Q({ id: 'c-prev', module: 'discrimination', level: 'apply', stem: 'A model moves from a setting with 20% prevalence to one with 5%, with the same sensitivity and specificity. What changes?', options: ['The ROC curve', 'PPV falls and NPV rises', 'Sensitivity falls', 'AUC falls'], answer: 1, explanation: 'Sensitivity, specificity and ROC are conditional on true status; predictive values depend on prevalence.' }),

  // ── 9 Calibration ───────────────────────────────────────────────────────────
  Q({ id: 'cal-slope', module: 'calibration', level: 'apply', stem: 'At external validation, a model’s calibration slope is 0.7. What does this mean?', options: ['Predictions are too modest', 'Predictions are too extreme: high risks over-estimated and low risks under-estimated — typical of overfitting', 'Average risk is over-estimated by 30%', 'AUC is 0.7'], answer: 1, explanation: 'Slope < 1 indicates the spread of predictions is too wide. It is the signature of overfitting in development.', refs: ['vancalster2016hierarchy'] }),
  Q({ id: 'cal-imbalance', module: 'calibration', level: 'appraise', stem: 'A model developed in a tertiary referral centre is applied in primary care, where the outcome is much rarer. Which calibration problem is most likely?', options: ['Slope > 1', 'Over-prediction on average (calibration intercept < 0, O/E < 1)', 'Under-prediction', 'None, if AUC is preserved'], answer: 1, explanation: 'The intercept encodes the development setting’s baseline risk. In a lower-risk setting the model over-predicts; an intercept update is the first fix.' }),
  Q({ id: 'cal-hl', module: 'calibration', level: 'recall', stem: 'Why is the Hosmer–Lemeshow test not recommended for assessing calibration?', options: ['It is too conservative', 'It depends on arbitrary grouping and sample size and gives no information on the size or direction of miscalibration', 'It requires a survival outcome', 'It only works for neural networks'], answer: 1, explanation: 'Use calibration plots with flexible curves, the intercept and slope, and ICI instead.', refs: ['steyerberg2019book'] }),
  Q({ id: 'cal-invariant', module: 'calibration', level: 'apply', stem: 'Every prediction of a model is squared (p → p²). What happens to AUC and calibration?', options: ['Both unchanged', 'AUC unchanged; calibration changes', 'AUC falls; calibration unchanged', 'Both change'], answer: 1, explanation: 'Squaring is monotone on [0, 1], so the ranking (AUC) is preserved, but the probabilities change.' }),
  Q({ id: 'cal-citl', module: 'calibration', level: 'recall', stem: 'The calibration intercept (estimated with logit(p̂) as an offset) is −0.5. Interpretation?', options: ['Average risk is under-predicted', 'Average risk is over-predicted', 'Predictions are too extreme', 'Perfect calibration'], answer: 1, explanation: 'A negative correction is needed to bring predictions down to observed rates, so the model over-predicts on average.' }),
  Q({ id: 'cal-brier', module: 'calibration', level: 'apply', stem: 'The Brier score is 0.08 where prevalence is 10%. What is the scaled Brier score?', options: ['0.11', '0.92', '0.80', '0.08'], answer: 0, explanation: 'Reference Brier = 0.1 × 0.9 = 0.09. Scaled = 1 − 0.08/0.09 = 0.11. A raw Brier of 0.08 sounds good but is only modestly better than predicting 10% for everyone.', refs: ['steyerberg2010framework'] }),
  Q({ id: 'cal-recal', module: 'calibration', level: 'recall', stem: 'Logistic recalibration (Platt scaling) of a boosted model should be fitted:', options: ['On the training data used to grow the trees', 'On separate data, with performance then reported on yet other data or via cross-validation', 'On the final test set and reported there', 'It is unnecessary for boosted models'], answer: 1, explanation: 'Recalibration fitted on training data inherits overfitting; fitting and evaluating on the same test data is optimistic.' }),

  // ── 10 Utility ──────────────────────────────────────────────────────────────
  Q({ id: 'u-threshold', module: 'utility', level: 'apply', stem: 'A clinician would accept 4 unnecessary biopsies to find one cancer. What risk threshold does this imply?', options: ['4%', '20%', '25%', '80%'], answer: 1, explanation: 'Threshold odds = harm/benefit = 1/4, so p_t = 1/(1+4) = 20%.', refs: ['vickers2006dca'] }),
  Q({ id: 'u-nb', module: 'utility', level: 'apply', stem: 'Among 1,000 patients at a 10% threshold, the model gives 60 true positives and 200 false positives. What is its net benefit?', options: ['0.038', '0.060', '−0.140', '0.040'], answer: 0, explanation: 'NB = 60/1000 − (200/1000) × (0.1/0.9) = 0.060 − 0.022 = 0.038, i.e., 3.8 net true positives per 100 patients.' }),
  Q({ id: 'u-treatall', module: 'utility', level: 'apply', stem: 'Prevalence is 10%. At a threshold of 20%, what is the net benefit of treating everyone?', options: ['0.10', '0.00', '−0.125', '0.08'], answer: 2, explanation: 'NB(all) = 0.10 − 0.90 × (0.2/0.8) = 0.10 − 0.225 = −0.125. Treating everyone is worse than treating no one at this threshold.' }),
  Q({ id: 'u-read', module: 'utility', level: 'appraise', stem: 'A decision curve shows the model above both treat-all and treat-none for thresholds 5–30%, and below treat-none above 35%. What is the right conclusion?', options: ['The model is useless', 'The model is useful for decisions whose reasonable threshold lies between 5% and 30%', 'The model should be used at 40%', 'Net benefit cannot be interpreted without an AUC'], answer: 1, explanation: 'Read decision curves over the range of clinically plausible thresholds for the intended decision.', refs: ['vickers2019guide'] }),
  Q({ id: 'u-impact', module: 'utility', level: 'recall', stem: 'What is the strongest feasible design for evaluating whether a deterioration alert reduces mortality across hospital wards?', options: ['Retrospective AUC on historical data', 'A cluster-randomised or stepped-wedge trial', 'A clinician satisfaction survey', 'Comparing alerted and non-alerted patients'], answer: 1, explanation: 'Alerts act through clinicians and wards, so randomising clusters avoids contamination; comparing alerted vs non-alerted patients is confounded by risk.', refs: ['kappen2018impact'] }),
  Q({ id: 'u-capacity', module: 'utility', level: 'apply', stem: 'A rapid-response team can review 10 patients per day. Which evaluation is most relevant?', options: ['AUC across all patients', 'Sensitivity and PPV among the 10 highest-risk patients each day', 'Accuracy at a 50% threshold', 'The Brier score'], answer: 1, explanation: 'Under fixed capacity the operating point is "top-k". Evaluate how many true cases that list contains, and what share of all cases it captures.' }),

  // ── 11 Interpretability ─────────────────────────────────────────────────────
  Q({ id: 'i-perm', module: 'interpretability', level: 'appraise', stem: 'Creatinine and urea are highly correlated. In a boosted model, permutation importance is low for both. Why might that be?', options: ['Kidney function is irrelevant to the outcome', 'When one is shuffled the model can rely on the other, and shuffling creates unrealistic patients, so importance is shared or masked', 'Permutation importance only works for linear models', 'The model is miscalibrated'], answer: 1, explanation: 'Permutation importance measures reliance conditional on everything else the model sees. Correlated predictors substitute for each other (Hooker 2021). Permute them together or use grouped importance.', refs: ['hooker2021permute'] }),
  Q({ id: 'i-shap', module: 'interpretability', level: 'apply', stem: 'For one patient, the SHAP baseline is −2.0 log-odds and the SHAP values are +0.8, +0.5 and −0.3. What is the predicted probability?', options: ['27%', '0%', '50%', '12%'], answer: 0, explanation: 'Log-odds = −2.0 + 0.8 + 0.5 − 0.3 = −1.0. p = 1/(1 + e) ≈ 27%. Additivity holds on the log-odds scale.' }),
  Q({ id: 'i-causal', module: 'interpretability', level: 'appraise', stem: 'SHAP shows that "lactate ordered in the last 6 h" makes the largest contribution to a sepsis model’s predictions. Which conclusion is justified?', options: ['Ordering lactate causes sepsis', 'The model relies on a marker of clinician suspicion — a possible proxy or leakage to investigate', 'Lactate should be ordered for everyone', 'The model is causal'], answer: 1, explanation: 'SHAP describes the model’s use of inputs. Here it reveals reliance on care-process information, which may not be available at the intended index time and will change if ordering practice changes.' }),
  Q({ id: 'i-rudin', module: 'interpretability', level: 'recall', stem: 'Rudin (2019) argued that for high-stakes decisions:', options: ['Black-box models should always be used with SHAP', 'Inherently interpretable models should be preferred over explaining black boxes, especially when they perform comparably', 'Explanations are unnecessary', 'Deep learning is required'], answer: 1, explanation: 'Post-hoc explanations are approximations that can be unfaithful; when an interpretable model is equally accurate, it avoids that problem.', refs: ['rudin2019'] }),
  Q({ id: 'i-jabbour', module: 'interpretability', level: 'recall', stem: 'In a randomised vignette study (Jabbour 2023), when clinicians were shown predictions from a systematically biased AI model:', options: ['Explanations fully protected their accuracy', 'Their diagnostic accuracy fell, and explanations did not significantly mitigate the harm', 'They ignored the model', 'Accuracy improved'], answer: 1, explanation: 'Explanations did not enable clinicians to detect and discount the biased model, so they cannot replace validation.', refs: ['jabbour2023'] }),
  Q({ id: 'i-lime', module: 'interpretability', level: 'recall', stem: 'A known limitation of LIME explanations is that they:', options: ['Can only be applied to linear models', 'Depend on the perturbation distribution and kernel width and can be unstable between runs', 'Always equal SHAP values', 'Require the training data labels'], answer: 1, explanation: 'LIME fits a local surrogate to perturbed samples; the result depends on choices about the neighbourhood.', refs: ['ribeiro2016lime'] }),

  // ── 12 Fairness ─────────────────────────────────────────────────────────────
  Q({ id: 'b-race', module: 'fairness', level: 'appraise', stem: 'A team removes race from a model’s inputs. What does this guarantee?', options: ['Equal calibration across racial groups', 'Equal error rates', 'Nothing by itself: proxies and labels can still produce disparities, so performance must be audited by group', 'Compliance with all regulations'], answer: 2, explanation: 'Postcode, insurance, utilisation and biased labels can carry the same information. Fairness is assessed by outcomes and errors by group, not by the input list.', refs: ['obermeyer2019', 'vyas2020'] }),
  Q({ id: 'b-impossible', module: 'fairness', level: 'appraise', stem: 'Two groups have different outcome prevalences. A risk score is perfectly calibrated in both, and one threshold is applied. What should you expect?', options: ['Identical sensitivity and false-positive rates', 'Different false-positive and true-positive rates between groups; equalising them would break calibration within groups', 'Different calibration', 'Equal PPV'], answer: 1, explanation: 'With unequal base rates and imperfect prediction, calibration within groups and equal error rates are mutually incompatible (Kleinberg 2017; Chouldechova 2017).', refs: ['kleinberg2017', 'chouldechova2017'] }),
  Q({ id: 'b-label', module: 'fairness', level: 'recall', stem: 'In Obermeyer et al. (2019), the main source of bias in the care-management algorithm was:', options: ['Inclusion of race as a predictor', 'Using healthcare cost as the label, which reflects unequal access as well as health need', 'A small sample size', 'Overfitting'], answer: 1, explanation: 'The algorithm accurately predicted cost; cost under-represents need in groups with less access. Re-labelling on health measures greatly reduced the bias.', refs: ['obermeyer2019'] }),
  Q({ id: 'b-oximetry', module: 'fairness', level: 'recall', stem: 'Pulse oximeters missing occult hypoxaemia more often in Black patients is an example of:', options: ['Label bias', 'Measurement bias in an input', 'Representation bias', 'Deployment bias'], answer: 1, explanation: 'The input itself is measured with group-dependent error (Sjoding 2020). Any model using SpO₂ inherits it.', refs: ['sjoding2020'] }),
  Q({ id: 'b-audit', module: 'fairness', level: 'apply', stem: 'Which subgroup audit is most informative for an alert that will be used at a fixed threshold?', options: ['AUC by group only', 'Calibration (O/E, slope) and sensitivity and PPV at the deployment threshold, by group, with confidence intervals', 'Overall accuracy', 'The number of predictors'], answer: 1, explanation: 'Decisions happen at the threshold and depend on whether risks mean the same thing in each group. AUC alone can hide threshold-level disparities.' }),
  Q({ id: 'b-ckd', module: 'fairness', level: 'recall', stem: 'The 2021 CKD-EPI equations and the 2024 AHA PREVENT equations have in common that they:', options: ['Use machine learning', 'Estimate without a race term', 'Apply only to children', 'Were never externally validated'], answer: 1, explanation: 'Both moved away from race-based adjustment (Inker 2021; Khan 2024).', refs: ['inker2021', 'khan2024prevent'] }),

  // ── 13 Deployment ───────────────────────────────────────────────────────────
  Q({ id: 'dep-feedback', module: 'deployment', level: 'appraise', stem: 'After go-live, patients flagged by a deterioration model receive an effective intervention. If the model is retrained naively on post-deployment outcomes, it will most likely:', options: ['Improve', 'Learn that high-risk patterns are less dangerous, under-predicting risk for future patients', 'Be unaffected', 'Become better calibrated'], answer: 1, explanation: 'Interventions prevent outcomes in flagged patients, contaminating labels — "victims of their own success" (Lenert 2019). Retraining needs designs that account for treatment.', refs: ['lenert2019'] }),
  Q({ id: 'dep-cds', module: 'deployment', level: 'apply', stem: 'Under the FDA’s statutory criteria for non-device clinical decision support, which software is most likely still a regulated device?', options: ['A guideline reminder that displays its rationale and sources to the physician', 'Software that analyses ECG waveforms to detect atrial fibrillation', 'A drug-interaction reference', 'A display of trended laboratory values'], answer: 1, explanation: 'Software that acquires, processes or analyses a medical signal or image fails the first criterion and remains a device, regardless of the January 2026 revisions.', refs: ['fda_cds2026'] }),
  Q({ id: 'dep-silent', module: 'deployment', level: 'recall', stem: 'What is the main purpose of a silent (shadow) deployment?', options: ['To train clinicians', 'To test live data pipelines and real-time performance without affecting care', 'To obtain regulatory approval', 'To measure clinical impact'], answer: 1, explanation: 'Real-time inputs often differ from retrospective extracts (timing, missingness, mapping). A silent trial catches these before patients are affected.' }),
  Q({ id: 'dep-prior', module: 'deployment', level: 'apply', stem: 'Monitoring shows rising incidence with stable AUC and O/E increasing month by month. What is the appropriate response?', options: ['Rebuild the model with deep learning', 'Update the intercept (recalibrate) and continue monitoring', 'Ignore it, because AUC is stable', 'Lower every threshold by half'], answer: 1, explanation: 'This is prior (label) shift: ranking is preserved, so an intercept update restores calibration.' }),
  Q({ id: 'dep-hti5', module: 'deployment', level: 'recall', stem: 'What did ONC’s HTI-5 final rule (October 2026) change for predictive decision support interventions in certified EHRs?', options: ['It required FDA clearance for all predictive models', 'It removed requirements for certified health IT to support source attributes and predictive-DSI risk management', 'It banned predictive models in EHRs', 'It mandated external validation'], answer: 1, explanation: 'HTI-5 removed the HTI-1 source-attribute and predictive-DSI risk-management requirements (mostly effective January 2027), shifting transparency to procurement and local governance.', refs: ['onc_hti5'] }),
  Q({ id: 'dep-automation', module: 'deployment', level: 'recall', stem: 'Dratsch et al. (2023) studied radiologists reading mammograms with AI suggestions. When the AI suggested incorrect categories:', options: ['Readers were unaffected', 'Reader accuracy fell sharply, especially for less experienced readers', 'Only experts were affected', 'Accuracy improved'], answer: 1, explanation: 'This is automation bias, and experience offered only partial protection. Interfaces and training must support appropriate reliance.', refs: ['dratsch2023'] }),
  Q({ id: 'dep-eu', module: 'deployment', level: 'recall', stem: 'Under the EU AI Act, an AI system that is a medical device (or a safety component of one) is classed as:', options: ['Minimal risk', 'Limited risk (transparency only)', 'High-risk', 'Prohibited'], answer: 2, explanation: 'Medical-device AI is high-risk, with obligations alongside MDR/IVDR. The 2026 Digital Omnibus agreement postpones the application dates for product-embedded systems.', refs: ['euaiact2024', 'eu_omnibus2026'] }),

  // ── 14 LLMs ─────────────────────────────────────────────────────────────────
  Q({ id: 'llm-evidence', module: 'llm', level: 'recall', stem: 'In a randomised trial (Goh 2024), giving physicians access to an LLM for diagnostic cases:', options: ['Substantially improved their diagnostic reasoning', 'Did not significantly improve their reasoning compared with conventional resources, although the LLM alone scored higher', 'Reduced their accuracy', 'Was not compared with conventional resources'], answer: 1, explanation: 'Model capability did not automatically translate into better human performance; how tools are integrated and used matters.', refs: ['goh2024'] }),
  Q({ id: 'llm-eval', module: 'llm', level: 'apply', stem: 'Which is the most appropriate evaluation of an LLM that drafts discharge summaries?', options: ['Accuracy on medical licensing questions', 'Local real records, blinded clinician raters using a severity-graded error and omission taxonomy, comparison with current summaries, and a pinned model version', 'User satisfaction only', 'Automatic text-similarity scores against the original notes'], answer: 1, explanation: 'Task-specific, real-world, severity-weighted human evaluation with reporting per TRIPOD-LLM. Exam scores and similarity metrics do not capture clinical safety.', refs: ['gallifant2025tripodllm'] }),
  Q({ id: 'llm-conf', module: 'llm', level: 'appraise', stem: 'An LLM says it is "95% confident" in a diagnosis. How should this be treated?', options: ['As a calibrated probability', 'As unreliable until its stated confidence is empirically checked against outcomes; verbalised confidence tends to be over-confident', 'As a lower bound', 'As equivalent to a PPV of 95%'], answer: 1, explanation: 'Verbalised confidence is poorly calibrated (Xiong 2024). Treat it like any uncalibrated score.', refs: ['xiong2024uncertainty'] }),
  Q({ id: 'llm-bedi', module: 'llm', level: 'recall', stem: 'A 2025 systematic review of LLM evaluations in health care (Bedi 2025) found that real patient-care data were used in about:', options: ['5% of studies', '25%', '50%', '80%'], answer: 0, explanation: 'Most studies used exam questions or vignettes and measured accuracy alone, leaving real-world performance largely untested.', refs: ['bedi2025'] }),
  Q({ id: 'llm-predict', module: 'llm', level: 'appraise', stem: 'A team proposes using an LLM to estimate 30-day mortality from admission notes. What evidence should be required?', options: ['The LLM’s exam scores', 'The same as for any prediction model: defined index time, leakage control, discrimination, calibration, net benefit and external validation, compared with a simple baseline', 'Only a qualitative review', 'None, if the vendor is reputable'], answer: 1, explanation: 'Model type does not change the evaluation standard.' }),
  Q({ id: 'llm-version', module: 'llm', level: 'recall', stem: 'A vendor silently updates the LLM behind a deployed clinical tool. What is the key risk?', options: ['None, because newer models are always better', 'Behaviour and performance can change unpredictably; pin versions, regression-test prompts and monitor', 'Only latency changes', 'The tool becomes a regulated device'], answer: 1, explanation: 'LLM outputs are sensitive to the model version; previous validation may no longer hold.' }),

  // ── 15 Causal inference ─────────────────────────────────────────────────────
  Q({ id: 'cau-cfpred', module: 'causal', level: 'appraise', stem: 'A clinician wants a patient’s stroke risk *if they do not start* anticoagulation, using a prediction model developed in a cohort where many patients were anticoagulated. What is the main problem?', options: ['None — prediction models give untreated risk by definition', 'The model predicts risk under the treatment mix in the development data; risk under a specific treatment choice is a counterfactual prediction that needs causal assumptions and handling of treatment', 'The model needs a higher AUC', 'Only the calibration slope needs updating'], answer: 1, explanation: 'Treatment-naive risk is a causal quantity. Models developed where effective treatment was common under-estimate untreated risk (treatment paradox); counterfactual prediction requires adjusting for treatment and confounding.', refs: ['dickerman2020cfpred', 'vangeloven2020'] }),
  Q({ id: 'cau-exch', module: 'causal', level: 'recall', stem: 'Which condition means that, given measured covariates, treated and untreated patients would have had the same outcome distribution under the same treatment?', options: ['Positivity', 'Consistency', 'Exchangeability (no unmeasured confounding)', 'Proportional hazards'], answer: 2, explanation: 'Exchangeability conditional on L is the "no unmeasured confounding" condition. Positivity requires a non-zero probability of each treatment for every type of patient; consistency requires well-defined interventions.', refs: ['hernanrobins2020'] }),
  Q({ id: 'cau-collider', module: 'causal', level: 'appraise', stem: 'Among infants with low birth weight, those of mothers who smoked have *lower* mortality than those of non-smokers. What is the most likely explanation?', options: ['Smoking protects low-birth-weight infants', 'Collider bias: birth weight is affected by smoking and by other, more lethal causes; conditioning on it creates a spurious association', 'Confounding by maternal age', 'Measurement error in birth weight'], answer: 1, explanation: 'Low birth weight from smoking is less dangerous than low birth weight from other causes (e.g., malformations). Restricting to low-birth-weight infants opens a non-causal path (Hernández-Díaz 2006).', refs: ['hernandezdiaz2006', 'hernan2004selection'] }),
  Q({ id: 'cau-mediator', module: 'causal', level: 'apply', stem: 'You want the *total* effect of an antihypertensive on stroke. Should you adjust for blood pressure measured after treatment started?', options: ['Yes — it is a strong predictor of stroke', 'No — it is a mediator on the causal pathway; adjusting removes part of the effect you want to estimate', 'Yes — it is a confounder', 'Only if the p-value is below 0.05'], answer: 1, explanation: 'Post-treatment blood pressure lies on the pathway A → BP → stroke. Adjusting for it estimates (at best) a direct effect, not the total effect relevant to prescribing.' }),
  Q({ id: 'cau-immortal', module: 'causal', level: 'appraise', stem: 'In a cohort followed from MI discharge, "statin users" are patients with any dispensing in the following year and are compared with non-users from the discharge date. The hazard ratio for death is 0.6. What is the main problem?', options: ['Confounding by indication only', 'Immortal time bias: users had to survive until their first dispensing, and that time is counted as exposed', 'Too few events', 'Non-proportional hazards'], answer: 1, explanation: 'Exposure is defined using information after time zero. Align eligibility, assignment and follow-up (time-varying exposure, landmark, or clone–censor–weight). See the immortal time lab.', refs: ['suissa2008immortal', 'hernan2016immortal'] }),
  Q({ id: 'cau-protocol', module: 'causal', level: 'recall', stem: 'In a target trial emulation, which three elements should coincide at time zero?', options: ['Outcome ascertainment, censoring and analysis', 'Meeting eligibility criteria, assignment to a treatment strategy, and start of follow-up', 'Diagnosis, first prescription and death', 'Randomisation, blinding and allocation concealment'], answer: 1, explanation: 'When eligibility, assignment and follow-up start together — as in a randomised trial — immortal time and prevalent-user biases are avoided by design.', refs: ['hernan2016target', 'hernan2016immortal'] }),
  Q({ id: 'cau-balance', module: 'causal', level: 'appraise', stem: 'After inverse probability of treatment weighting, all standardised mean differences of measured covariates are below 0.05. What can you conclude?', options: ['Confounding has been eliminated', 'Measured covariates are balanced; unmeasured confounding may still be present', 'The propensity model is causal', 'The result is equivalent to a randomised trial'], answer: 1, explanation: 'Weighting can only balance what is measured. Exchangeability with respect to unmeasured factors is an untestable assumption — address it with design, negative controls and sensitivity analyses.', refs: ['austin2011ps'] }),
  Q({ id: 'cau-positivity', module: 'causal', level: 'appraise', stem: 'A propensity-score model has a C-statistic of 0.97 and some inverse-probability weights exceed 100. What does this indicate?', options: ['An excellent propensity model', 'Near-violations of positivity: some patients almost always or never receive treatment; reconsider the population or estimand (e.g., overlap weights) rather than trusting the estimate', 'Unmeasured confounding has been removed', 'The outcome model is misspecified'], answer: 1, explanation: 'Propensity models are not judged by discrimination; near-perfect separation means little overlap, unstable weights and estimates driven by a few patients.', refs: ['petersen2012positivity'] }),
  Q({ id: 'cau-evalue', module: 'causal', level: 'apply', stem: 'An observational study reports a risk ratio of 2.0. What is the E-value for the point estimate?', options: ['2.0', '3.41', '4.0', '1.41'], answer: 1, explanation: 'E = RR + √(RR(RR − 1)) = 2 + √2 = 3.41. An unmeasured confounder would need risk-ratio associations of 3.41 with both treatment and outcome (beyond measured covariates) to explain the estimate away.', refs: ['vanderweele2017evalue'] }),
  Q({ id: 'cau-table2', module: 'causal', level: 'appraise', stem: 'A paper estimating the effect of exercise on mortality presents a table of all coefficients from its adjusted model, and the discussion interprets the smoking coefficient as the effect of smoking. What is wrong?', options: ['Nothing', 'The Table 2 fallacy: covariate coefficients are not total causal effects — the model was built to adjust for confounding of exercise, not of smoking', 'Smoking should have been excluded', 'The model needs more interactions'], answer: 1, explanation: 'Each causal question needs its own adjustment set. Some covariates are adjusted for their own mediators (e.g., smoking → lung function), so their coefficients are at best direct effects (Westreich & Greenland 2013).', refs: ['westreich2013table2'] }),
  Q({ id: 'cau-timevarying', module: 'causal', level: 'recall', stem: 'In HIV care, CD4 count affects later treatment decisions and is itself affected by earlier treatment. Which approach is appropriate for the effect of a sustained treatment strategy?', options: ['Standard regression adjusting for the latest CD4 count', 'Ignore CD4 count', 'g-methods such as inverse-probability-weighted marginal structural models or the g-formula', 'A propensity score at baseline only'], answer: 2, explanation: 'Time-varying confounders affected by prior treatment make conventional adjustment biased whether you adjust or not; g-methods handle this (Robins 2000).', refs: ['robins2000msm'] }),
  Q({ id: 'cau-rctdup', module: 'causal', level: 'recall', stem: 'What did the RCT-DUPLICATE initiative (2023) show about database emulations of 32 randomised trials?', options: ['Observational analyses never agree with trials', 'Agreement was reasonable overall and higher when trial designs could be closely emulated; divergence reflected emulation differences, chance and residual confounding', 'Observational estimates were always larger', 'Agreement was perfect'], answer: 1, explanation: 'Correlation was 0.82 overall and 0.93 in a post-hoc subset of closely emulated trials. Emulation quality, not data volume, drove agreement.', refs: ['wang2023rctduplicate'] }),
];

export const questionsByModule = (moduleId: string) => questions.filter((q) => q.module === moduleId);
export const questionById = (id: string) => questions.find((q) => q.id === id);
